from decimal import Decimal


def _value(source: dict | None, key: str) -> object:
    if not source:
        return ""
    value = source.get(key, "")
    return "" if value is None else value


def _text(value: object) -> str:
    return "" if value is None else str(value)


def _nvl(value: object, default: object) -> object:
    if value is None or value == "":
        return default
    return value


def _number(value: object) -> Decimal:
    if value is None or value == "":
        return Decimal(0)
    return Decimal(str(value))


def _date_equal(left: object, right: object) -> bool:
    left_text = _text(left)
    right_text = _text(right)
    if left_text == "00000000" or right_text == "00000000":
        return left_text == "00000000" and right_text == "00000000"
    return left_text == right_text


def _date_greater_equal(left: object, right: object) -> bool:
    left_text = _text(left)
    right_text = _text(right)
    if left_text == "00000000" or right_text == "00000000":
        return False
    return left_text >= right_text


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    errors: list[dict] = []
    current = record if record is not None else {}
    previous = old if event == "UPDATE" and old is not None else {}

    def failure(code: str, message: str, severity: str = "BLOCK") -> None:
        errors.append(
            {
                "code": code,
                "message": message,
                "severity": severity,
            }
        )

    amount = _number(_nvl(_value(current, "AMT"), 0))
    status = _text(_value(current, "STAT_CD"))
    lost_reason = _text(_value(current, "LOST_RSN"))
    close_date = _text(_value(current, "CLOSE_DT"))
    stage_pct = _number(_value(current, "STAGE_PCT"))

    if event in ("INSERT", "UPDATE"):
        if not (amount >= 0):
            failure("E3001", "Amount negative")

        if not (status == "W" and amount == 0):
            pass
        else:
            failure("E3002", "Won opportunity requires amount")

        if not (status == "L" and lost_reason == ""):
            pass
        else:
            failure("E3003", "Lost reason required")

        if not (status == "W" and _date_equal(close_date, "00000000")):
            pass
        else:
            failure("E3004", "Won opportunity requires close date")

        if status == "P":
            stage_ok = stage_pct == 10
        elif status == "Q":
            stage_ok = stage_pct == 25
        elif status == "N":
            stage_ok = stage_pct == 60
        elif status == "W":
            stage_ok = stage_pct == 100
        elif status == "L":
            stage_ok = stage_pct == 0
        else:
            stage_ok = False

        if not stage_ok:
            failure("E3006", "Stage percent inconsistent with status")

    if event == "UPDATE":
        old_status = _text(_value(previous, "STAT_CD"))
        if not (old_status == "W" and status != "W"):
            pass
        else:
            failure("E3005", "Cannot reopen a won opportunity")

    if event == "INSERT":
        if not (
            _date_equal(close_date, "00000000")
            or _date_greater_equal(close_date, today)
        ):
            failure("E3007", "Close date in past", "WARN")

    return errors


def is_blocked(errors: list[dict]) -> bool:
    return any(error.get("severity") == "BLOCK" for error in errors)
